import { decodeFunctionData, encodeFunctionData, parseAbi } from 'viem';

import type { EthereumSignTransaction } from '../../src';
import type { ReviewField } from '../tests/device/clearSigningReview';

export type ClearSigningScenario = {
    name: string;
    transaction: EthereumSignTransaction['transaction'] & { to: string; data: string };
    definitionPath: string;
    providers: string[];
    intent: string;
    reviewFields: ReviewField[];
    knownRawFallback?: { url: string; reason: string; definitionHash: string };
};

const transactionDefaults = {
    chainId: 1,
    nonce: '0x0',
    gasPrice: '0x3b9aca00',
    gasLimit: '0x7a120',
};

const fusionScenario: ClearSigningScenario = {
    name: 'USDT to WETH via 1inch Fusion settlement (full taker amount)',
    // Inner router call from trace [0, 0]; the outer resolver transaction is not replayed.
    // https://etherscan.io/tx/0x4068449d5acd8ba35e86a461cf308a776426b1cc21c72a0374aa4ad2d55c5728
    // Use taker-amount mode with a zero threshold; keep the signed order and extension intact.
    transaction: {
        ...transactionDefaults,
        to: '0x111111125421cA6dc452d289314280a0f8842A65',
        value: '0x0',
        data: '',
    },
    definitionPath: 'display-format/111111125421ca6dc452d289314280a0f8842a65-f497df75.dat',
    providers: ['1inch Network'],
    intent: 'Fill order',
    // The maker swaps USDT to WETH; the resolver reviews the opposite side of the order.
    reviewFields: [
        { label: 'Order selling amount', value: '0.002089277801260739 WETH' },
        { label: 'Order purchasing amt', value: '5 USDT' },
        { label: 'Amount to sell', value: '0.002089277801260739 WETH' },
    ],
};

export const clearSigningScenarios: ClearSigningScenario[] = [
    {
        name: 'Lido wrap',
        transaction: {
            ...transactionDefaults,
            to: '0x7f39C581F595B53c5cb19bD0b3f8dA6c935E2Ca0',
            value: '0x0',
            // From the Connect clear-signing test: wrap 0.999999999999999998 stETH.
            data: '0xea598cb00000000000000000000000000000000000000000000000000de0b6b3a763fffe',
        },
        definitionPath: 'display-format/7f39c581f595b53c5cb19bd0b3f8da6c935e2ca0-ea598cb0.dat',
        providers: ['Lido DAO'],
        intent: 'Wrap stETH',
        reviewFields: [{ label: 'stETH amount', value: '0.999999999999999998 STETH' }],
    },
    {
        name: 'ETH to PEPE via 1inch Classic',
        // Recorded swap calldata and value; nonce, gas and signing account are test-specific.
        // https://etherscan.io/tx/0x982ffc108d6492345adb3ca797df0ea4eb5cbd5931508dff0b475d1beb4c9e62
        transaction: {
            ...transactionDefaults,
            to: '0x111111125421cA6dc452d289314280a0f8842A65',
            value: '0x44f1656a2393c0',
            data: '',
        },
        definitionPath: 'token-6982508145454ce325ddbe47a25d4ec3d2311933.dat',
        providers: ['1inch Aggregation Router V6', '1inch Network'],
        intent: 'Swap',
        reviewFields: [
            { label: 'Amount to Send', value: '0.019405716291032 ETH' },
            { label: 'Minimum to Receive', value: '12,921,677.099342507099490877 PEPE' },
        ],
    },
    {
        name: 'USDT to WETH via 1inch Classic',
        // Synthetic swap ABI vector: 50 USDT for at least 0.01 WETH, with no executor route.
        // Signing-only coverage; the empty executor data is not intended for on-chain execution.
        // https://github.com/ethereum/clear-signing-erc7730-registry/blob/master/registry/1inch/common-AggregationRouterV6.json
        transaction: {
            ...transactionDefaults,
            to: '0x111111125421cA6dc452d289314280a0f8842A65',
            value: '0x0',
            data: '',
        },
        definitionPath: 'token-c02aaa39b223fe8d0a0e5c4f27ead9083c756cc2.dat',
        providers: ['1inch Aggregation Router V6', '1inch Network'],
        intent: 'Swap',
        reviewFields: [
            { label: 'Amount to Send', value: '50 USDT' },
            { label: 'Minimum to Receive', value: '0.01 WETH' },
        ],
    },
    fusionScenario,
];

const fusionABI = parseAbi([
    'function fillOrderArgs((uint256 salt, uint256 maker, uint256 receiver, uint256 makerAsset, uint256 takerAsset, uint256 makingAmount, uint256 takingAmount, uint256 makerTraits) order, bytes32 r, bytes32 vs, uint256 amount, uint256 takerTraits, bytes args)',
]);
const { args: fusionArgs } = decodeFunctionData({
    abi: fusionABI,
    data: fusionScenario.transaction.data as `0x${string}`,
});
const [order, r, vs, , takerTraits, args] = fusionArgs;

// Change only the requested fill amount and its mode; preserve the signed order and extension.
// https://github.com/1inch/limit-order-protocol/blob/master/contracts/libraries/TakerTraitsLib.sol
const fusionCalldata = (amount: bigint, isMakerAmount: boolean) =>
    encodeFunctionData({
        abi: fusionABI,
        functionName: 'fillOrderArgs',
        args: [
            order,
            r,
            vs,
            amount,
            isMakerAmount ? takerTraits | (1n << 255n) : takerTraits,
            args,
        ],
    });

clearSigningScenarios.push({
    ...fusionScenario,
    name: 'USDT to WETH via 1inch Fusion settlement (partial taker amount)',
    transaction: {
        ...fusionScenario.transaction,
        data: fusionCalldata(1_044_638_900_630_369n, false),
    },
    reviewFields: [
        ...fusionScenario.reviewFields.slice(0, 2),
        { label: 'Amount to sell', value: '0.001044638900630369 WETH' },
    ],
});

for (const fill of [
    { name: 'full', amount: 5_000_000n, value: '5 USDT' },
    { name: 'partial', amount: 2_500_000n, value: '2.5 USDT' },
]) {
    clearSigningScenarios.push({
        ...fusionScenario,
        name: `USDT to WETH via 1inch Fusion settlement (${fill.name} maker amount)`,
        transaction: {
            ...fusionScenario.transaction,
            data: fusionCalldata(fill.amount, true),
        },
        reviewFields: [
            ...fusionScenario.reviewFields.slice(0, 2),
            { label: 'Amount to buy', value: fill.value },
        ],
        knownRawFallback: {
            url: 'https://github.com/ethereum/clear-signing-erc7730-registry/issues/2688',
            // The enum omits the maker flag (0x80), so firmware rejects the entire descriptor.
            // The same descriptor also binds the fill amount to the wrong asset (issue finding 3).
            reason: 'Maker flag 0x80 is missing from the production takerTraits enum',
            definitionHash: 'f016ecc4ee6a2175ebe26fe048a5dcf7e0c12f30b3a49b63bcc82d573355712a',
        },
    });
}
